package com.malikoil.intelligence
import java.io.ByteArrayOutputStream
import java.util.zip.ZipEntry
import java.util.zip.ZipOutputStream
import java.time.*
import java.math.BigDecimal
/** Offline report snapshots. No macros, external links, executable formulas from source text or paid SDK. */
object DailyWorkbook{
 private data class Cell(val value:String,val number:Boolean=false,val style:Int=0,val formula:String?=null)
 private fun text(value:Any?)=Cell(value?.toString().orEmpty())
 private fun num(value:Any?,style:Int=2)=if(value==null)text("")else Cell(value.toString(),true,style)
 private fun excelTime(epoch:Long,dateOnly:Boolean=false):Cell{val t=Instant.ofEpochMilli(epoch).atZone(DailyRateReport.zone);val serial=t.toLocalDate().toEpochDay()+25569.0+(if(dateOnly)0.0 else t.toLocalTime().toSecondOfDay()/86400.0);return num(serial,if(dateOnly)4 else 3)}
 private fun x(value:String)=value.filter{it=='\n'||it=='\r'||it=='\t'||it.code>=32&&it.code!=0xFFFE&&it.code!=0xFFFF}.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&apos;")
 private fun col(index:Int):String{var n=index+1;var result="";while(n>0){result=('A'+(n-1)%26)+result;n=(n-1)/26};return result}
 private const val ns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"
 private const val rel="http://schemas.openxmlformats.org/officeDocument/2006/relationships"
 private fun sheet(rows:List<List<Cell>>,widths:List<Int>,chart:Boolean=false):String=buildString{
  append("<?xml version=\"1.0\" encoding=\"UTF-8\"?><worksheet xmlns=\"$ns\" xmlns:r=\"$rel\"><sheetViews><sheetView workbookViewId=\"0\"><pane ySplit=\"1\" topLeftCell=\"A2\" activePane=\"bottomLeft\" state=\"frozen\"/></sheetView></sheetViews><cols>")
  widths.forEachIndexed{i,w->append("<col min=\"${i+1}\" max=\"${i+1}\" width=\"$w\" customWidth=\"1\"/>")};append("</cols><sheetData>")
  rows.forEachIndexed{r,row->append("<row r=\"${r+1}\" ht=\"${if(r==0)70 else if(row.any{it.value.length>200})80 else 32}\" customHeight=\"1\">");row.forEachIndexed{c,cell->val ref=col(c)+(r+1);val style=if(r==0)1 else cell.style;if(cell.number){append("<c r=\"$ref\" s=\"$style\"><v>${cell.value}</v></c>")}else if(cell.formula!=null){append("<c r=\"$ref\" s=\"$style\"${if(cell.value.isEmpty())" t=\"str\"" else ""}><f>${x(cell.formula)}</f><v>${x(cell.value)}</v></c>")}else append("<c r=\"$ref\" s=\"$style\" t=\"inlineStr\"><is><t xml:space=\"preserve\">${x(cell.value)}</t></is></c>")};append("</row>")};append("</sheetData>")
  if(rows.size>1)append("<autoFilter ref=\"A1:${col(rows.maxOf{it.size}.coerceAtLeast(1)-1)}${rows.size}\"/>")
  append("<pageMargins left=\"0.3\" right=\"0.3\" top=\"0.5\" bottom=\"0.5\" header=\"0.2\" footer=\"0.2\"/>");if(chart)append("<drawing r:id=\"rId1\"/>");append("</worksheet>")
 }
 fun write(report:DailyRateReport):ByteArray{
  val output=ByteArrayOutputStream();val zip=ZipOutputStream(output);fun put(name:String,value:String){zip.putNextEntry(ZipEntry(name));zip.write(value.toByteArray(Charsets.UTF_8));zip.closeEntry()}
  val summary=mutableListOf(listOf(text("Malik Oil daily report"),text(report.date)));report.summary.lines().forEach{summary.add(listOf(text(it)))};summary.add(listOf(text("Generated at (Asia/Karachi)"),excelTime(report.generatedAt)));summary.add(listOf(text("Snapshot: regenerate in the app when reviewed inputs change.")));summary.add(listOf(text("Chart: up to 4 matching streams; missing observations are gaps, not zero.")))
  val rateRows=mutableListOf(listOf("Commodity","Mandi","Grade","Original PKR","Original unit","PKR /40kg","Previous PKR /40kg","Change vs previous available","Observed at (Asia/Karachi)","Previous observed at","Source","Source message ID").map{ text(it) })
  report.rates.forEachIndexed{i,row->val r=row.rate;val n=i+2;val factor=when(r.unit){"kg"->"40";"40kg"->"1";else->"0.4"};val normalized=Cell(r.price40.toPlainString(),false,2,"D$n*$factor");val change=Cell(row.changePercent?.divide(BigDecimal(100))?.toPlainString().orEmpty(),false,5,"IF(G$n=\"\",\"\",(F$n-G$n)/G$n)");rateRows.add(listOf(text(r.commodity),text(r.market),text(r.grade),num(r.amount),text(r.unit),normalized,num(row.previous?.price40),change,excelTime(r.observedAt*1000),row.previous?.let{excelTime(it.observedAt*1000)}?:text(""),text(r.source),text(r.eventId)))}
  if(report.rates.isEmpty())rateRows.add(listOf(text("No reviewed observations for this day. Missing rates are not zero.")))
  val streams=report.history.map{it.stream}.distinct().sorted().take(4)
  val dates=(29 downTo 0).map{report.date.minusDays(it.toLong())}
  val series=streams.mapIndexed{i,stream->val sample=report.history.first{it.stream==stream};val label="${i+1}: ${sample.commodity} / ${sample.market} / ${sample.grade}";val values=dates.map{date->report.history.find{it.stream==stream&&Instant.ofEpochSecond(it.observedAt).atZone(DailyRateReport.zone).toLocalDate()==date}?.price40?.toPlainString()};Triple(label,sample.source,values)}
  val trendRows=mutableListOf(listOf(text("Observation date"))+series.map{text(it.first+"\nSource: "+it.second)})
  dates.forEachIndexed{i,date->trendRows.add(listOf(excelTime(date.atStartOfDay(DailyRateReport.zone).toInstant().toEpochMilli(),true))+series.map{num(it.third[i])})}
  trendRows.add(emptyList());trendRows.add(listOf(text("Reviewed history (PKR per 40kg)")));
  if(series.isEmpty())trendRows.add(listOf(text("No reviewed numeric history. A graph will appear after reviewed observations exist.")))
  val rawRows=mutableListOf(listOf("Captured at (not rate observation date)","Group","Unreviewed message text","Part","Message fingerprint").map{text(it)})
  report.raw.forEach{message->message.text.chunked(400).forEachIndexed{i,part->rawRows.add(listOf(excelTime(message.capturedAt),text(message.group),text(part),num(i+1,0),text(message.id)))}}
  if(report.raw.isEmpty())rawRows.add(listOf(text("No matching received notifications for this report day.")))
  val names=listOf("Summary","Rates","Trends","Unreviewed")
  val contentTypes=buildString{append("<?xml version=\"1.0\"?><Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/><Default Extension=\"xml\" ContentType=\"application/xml\"/><Override PartName=\"/xl/workbook.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml\"/><Override PartName=\"/xl/styles.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml\"/>");for(i in 1..4)append("<Override PartName=\"/xl/worksheets/sheet$i.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml\"/>");if(series.isNotEmpty())append("<Override PartName=\"/xl/drawings/drawing1.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.drawing+xml\"/><Override PartName=\"/xl/charts/chart1.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.drawingml.chart+xml\"/>");append("</Types>")}
  put("[Content_Types].xml",contentTypes);put("_rels/.rels","<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"$rel/officeDocument\" Target=\"xl/workbook.xml\"/></Relationships>")
  put("xl/workbook.xml","<workbook xmlns=\"$ns\" xmlns:r=\"$rel\"><bookViews><workbookView/></bookViews><sheets>"+names.mapIndexed{i,name->"<sheet name=\"$name\" sheetId=\"${i+1}\" r:id=\"rId${i+1}\"/>"}.joinToString("")+"</sheets><calcPr calcId=\"191029\" fullCalcOnLoad=\"1\"/></workbook>")
  put("xl/_rels/workbook.xml.rels","<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\">"+(1..4).joinToString(""){i->"<Relationship Id=\"rId$i\" Type=\"$rel/worksheet\" Target=\"worksheets/sheet$i.xml\"/>"}+"<Relationship Id=\"rId5\" Type=\"$rel/styles\" Target=\"styles.xml\"/></Relationships>")
  put("xl/styles.xml","""<styleSheet xmlns="$ns"><numFmts count="2"><numFmt numFmtId="164" formatCode="yyyy-mm-dd hh:mm"/><numFmt numFmtId="165" formatCode="yyyy-mm-dd"/></numFmts><fonts count="2"><font><sz val="11"/><name val="Calibri"/></font><font><b/><color rgb="FFFFFFFF"/><sz val="11"/><name val="Calibri"/></font></fonts><fills count="3"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FF176548"/><bgColor indexed="64"/></patternFill></fill></fills><borders count="1"><border/></borders><cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs><cellXfs count="6"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0" applyAlignment="1"><alignment vertical="top" wrapText="1"/></xf><xf numFmtId="0" fontId="1" fillId="2" borderId="0" xfId="0" applyAlignment="1"><alignment vertical="center" wrapText="1"/></xf><xf numFmtId="4" fontId="0" fillId="0" borderId="0" xfId="0" applyNumberFormat="1"/><xf numFmtId="164" fontId="0" fillId="0" borderId="0" xfId="0" applyNumberFormat="1"/><xf numFmtId="165" fontId="0" fillId="0" borderId="0" xfId="0" applyNumberFormat="1"/><xf numFmtId="10" fontId="0" fillId="0" borderId="0" xfId="0" applyNumberFormat="1"/></cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>""")
  put("xl/worksheets/sheet1.xml",sheet(summary,listOf(85,28)));put("xl/worksheets/sheet2.xml",sheet(rateRows,listOf(16,24,20,18,18,18,20,25,24,24,40,40)));put("xl/worksheets/sheet3.xml",sheet(trendRows,listOf(22)+series.map{40},series.isNotEmpty()));put("xl/worksheets/sheet4.xml",sheet(rawRows,listOf(26,30,85,10,40)))
  if(series.isNotEmpty()){
   val packageRel="http://schemas.openxmlformats.org/package/2006/relationships"
   put("xl/worksheets/_rels/sheet3.xml.rels","<Relationships xmlns=\"$packageRel\"><Relationship Id=\"rId1\" Type=\"$rel/drawing\" Target=\"../drawings/drawing1.xml\"/></Relationships>")
   put("xl/drawings/drawing1.xml","""<xdr:wsDr xmlns:xdr="http://schemas.openxmlformats.org/drawingml/2006/spreadsheetDrawing" xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main"><xdr:twoCellAnchor><xdr:from><xdr:col>0</xdr:col><xdr:colOff>0</xdr:colOff><xdr:row>34</xdr:row><xdr:rowOff>0</xdr:rowOff></xdr:from><xdr:to><xdr:col>8</xdr:col><xdr:colOff>0</xdr:colOff><xdr:row>55</xdr:row><xdr:rowOff>0</xdr:rowOff></xdr:to><xdr:graphicFrame macro=""><xdr:nvGraphicFramePr><xdr:cNvPr id="2" name="Reviewed historical rates"/><xdr:cNvGraphicFramePr/></xdr:nvGraphicFramePr><xdr:xfrm><a:off x="0" y="0"/><a:ext cx="0" cy="0"/></xdr:xfrm><a:graphic><a:graphicData uri="http://schemas.openxmlformats.org/drawingml/2006/chart"><c:chart xmlns:c="http://schemas.openxmlformats.org/drawingml/2006/chart" xmlns:r="$rel" r:id="rId1"/></a:graphicData></a:graphic></xdr:graphicFrame><xdr:clientData/></xdr:twoCellAnchor></xdr:wsDr>""")
   put("xl/drawings/_rels/drawing1.xml.rels","<Relationships xmlns=\"$packageRel\"><Relationship Id=\"rId1\" Type=\"$rel/chart\" Target=\"../charts/chart1.xml\"/></Relationships>")
   val chart=buildString{append("<c:chartSpace xmlns:c=\"http://schemas.openxmlformats.org/drawingml/2006/chart\"><c:chart><c:autoTitleDeleted val=\"1\"/><c:plotArea><c:layout/><c:lineChart><c:grouping val=\"standard\"/><c:varyColors val=\"0\"/>");series.forEachIndexed{i,ser->append("<c:ser><c:idx val=\"$i\"/><c:order val=\"$i\"/><c:tx><c:v>${x(ser.first)}</c:v></c:tx><c:marker><c:symbol val=\"circle\"/><c:size val=\"4\"/></c:marker><c:cat><c:numRef><c:f>'Trends'!${'$'}A${'$'}2:${'$'}A${'$'}31</c:f><c:numCache><c:formatCode>yyyy-mm-dd</c:formatCode><c:ptCount val=\"30\"/>");dates.forEachIndexed{j,date->append("<c:pt idx=\"$j\"><c:v>${date.toEpochDay()+25569}</c:v></c:pt>")};append("</c:numCache></c:numRef></c:cat><c:val><c:numRef><c:f>'Trends'!${'$'}${col(i+1)}${'$'}2:${'$'}${col(i+1)}${'$'}31</c:f><c:numCache><c:formatCode>0.00</c:formatCode><c:ptCount val=\"30\"/>");ser.third.forEachIndexed{j,value->if(value!=null)append("<c:pt idx=\"$j\"><c:v>$value</c:v></c:pt>")};append("</c:numCache></c:numRef></c:val><c:smooth val=\"0\"/></c:ser>")};append("<c:axId val=\"123\"/><c:axId val=\"456\"/></c:lineChart><c:catAx><c:axId val=\"123\"/><c:scaling><c:orientation val=\"minMax\"/></c:scaling><c:axPos val=\"b\"/><c:numFmt formatCode=\"mm-dd\" sourceLinked=\"0\"/><c:tickLblPos val=\"nextTo\"/><c:crossAx val=\"456\"/><c:crosses val=\"autoZero\"/><c:auto val=\"1\"/><c:lblAlgn val=\"ctr\"/><c:lblOffset val=\"100\"/></c:catAx><c:valAx><c:axId val=\"456\"/><c:scaling><c:orientation val=\"minMax\"/></c:scaling><c:axPos val=\"l\"/><c:majorGridlines/><c:numFmt formatCode=\"0.00\" sourceLinked=\"0\"/><c:tickLblPos val=\"nextTo\"/><c:crossAx val=\"123\"/><c:crosses val=\"autoZero\"/><c:crossBetween val=\"between\"/></c:valAx></c:plotArea><c:legend><c:legendPos val=\"b\"/><c:layout/></c:legend><c:plotVisOnly val=\"1\"/><c:dispBlanksAs val=\"gap\"/></c:chart></c:chartSpace>")}
   put("xl/charts/chart1.xml",chart)
  }
  zip.close();return output.toByteArray()
 }
}
